public interface IHasLength { int Length { get; } }

public void PrintLength(IHasLength value)
{
    Console.WriteLine(value.Length);
}

// Plain anonymous object will NOT compile unless it implements IHasLength

function getArgsArrayLike() {
  return { 0: 'a', 1: 'b', length: 2 };
}

const fake = getArgsArrayLike();
try {
  fake.map(x => x.toUpperCase()); // TypeError: fake.map is not a function
} catch (err) {
  console.error(err.message);
}

